using System;using System.Collections;using System.Collections.Generic;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;using LighFight.Runtime;
public class SelectedContentTests {
 sealed class Op:ISelectedAssetLoad {public bool done;public GameObject asset;public string error;public int releases;public bool IsDone=>done;public GameObject Asset=>asset;public string Error=>error;public void Dispose(){releases++;}}
 sealed class Provider:ISelectedAssetProvider {public Dictionary<string,Op> latest=new Dictionary<string,Op>();public List<Op> all=new List<Op>();public ISelectedAssetLoad Load(string key){var op=new Op();latest[key]=op;all.Add(op);return op;}}
 GameContent Catalog(int count=11){var c=ScriptableObject.CreateInstance<GameContent>();c.streamed=true;c.fighterAddresses=Enumerable.Range(0,count).Select(i=>"f"+i).ToArray();c.arenaAddresses=new[]{"a0","a1"};return c;}
 [Test]public void ElevenAddressRosterHasNoDirectAssets(){var c=Catalog();try{Assert.True(c.ValidateCatalog(out _));Assert.AreEqual(11,c.FighterCount);Assert.AreEqual(2,c.ArenaCount);Assert.IsNull(c.fighters);Assert.IsNull(c.arenas);}finally{UnityEngine.Object.DestroyImmediate(c);}}
 [Test]public void RejectsInlineRefsInStreamCatalog(){var c=Catalog();c.fighters=new GameObject[1];try{Assert.False(c.ValidateCatalog(out var error));Assert.AreEqual("stream_catalog_has_inline_assets",error);}finally{UnityEngine.Object.DestroyImmediate(c);}}
 [Test]public void LoadsOnlySelectedThreeAddresses(){var c=Catalog();var p=new Provider();using(var lease=new SelectedContentLease(c,3,10,1,p)){CollectionAssert.AreEquivalent(new[]{"f3","f10","a1"},p.latest.Keys);Assert.AreEqual(3,lease.UniqueAssetCount);}Assert.True(p.all.All(o=>o.releases==1));UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void SameFighterUsesOneAssetLoad(){var c=Catalog();var p=new Provider();using(var lease=new SelectedContentLease(c,4,4,0,p)){Assert.AreEqual(2,p.all.Count);}Assert.True(p.all.All(o=>o.releases==1));UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void PendingCancelReleasesEveryHandleExactlyOnce(){var c=Catalog();var p=new Provider();var lease=new SelectedContentLease(c,1,2,0,p);Assert.False(lease.IsDone);lease.Dispose();lease.Dispose();foreach(var op in p.all){op.done=true;Assert.AreEqual(1,op.releases);}Assert.IsNull(lease.Player);UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void FailureIsVisibleAndAllHandlesReleased(){var c=Catalog();var p=new Provider();var lease=new SelectedContentLease(c,1,2,0,p);p.latest["f1"].error="network";Assert.AreEqual("network",lease.Error);lease.Dispose();Assert.True(p.all.All(o=>o.releases==1));UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void InvalidSelectionLoadsNothing(){var c=Catalog();var p=new Provider();Assert.Throws<ArgumentOutOfRangeException>(()=>new SelectedContentLease(c,0,11,0,p));Assert.IsEmpty(p.all);UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void MetadataRosterAndLegacyRosterBothRetained(){var c=Catalog();var root=new GameObject();var game=root.AddComponent<Prototype>();game.content=c;Assert.AreEqual(11,game.RosterCount);c.streamed=false;c.fighters=new GameObject[8];Assert.AreEqual(8,game.RosterCount);UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void RejectsEmptyOrBlankAddress(){var c=Catalog();c.fighterAddresses[5]=" ";Assert.False(c.ValidateCatalog(out _));c.fighterAddresses=new string[0];Assert.False(c.ValidateCatalog(out _));UnityEngine.Object.DestroyImmediate(c);}
 [Test]public void RetryCreatesFreshRequestAfterFailure(){var c=Catalog();var p=new Provider();var first=new SelectedContentLease(c,0,1,0,p);p.latest["f0"].error="failed";first.Dispose();var retry=new SelectedContentLease(c,0,1,0,p);Assert.IsNull(retry.Error);Assert.AreEqual(6,p.all.Count);retry.Dispose();Assert.True(p.all.All(o=>o.releases==1));UnityEngine.Object.DestroyImmediate(c);}
}
